import{_ as i,c as n,o as a,ag as t}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Traveling-dfp","description":"","frontmatter":{"title":"Traveling-dfp"},"headers":[],"relativePath":"general/traveling-dfp.md","filePath":"general/traveling-dfp.md","lastUpdated":null}'),r={name:"general/traveling-dfp.md"};function o(s,e,l,p,g,c){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="traveling-dfp" tabindex="-1">Traveling-dfp <a class="header-anchor" href="#traveling-dfp" aria-label="Permalink to &quot;Traveling-dfp&quot;">​</a></h1><h2 id="reporter-s-guide-to-device-and-personal-security-in-the-field" tabindex="-1">Reporter’s Guide to Device and Personal Security in the Field <a class="header-anchor" href="#reporter-s-guide-to-device-and-personal-security-in-the-field" aria-label="Permalink to &quot;Reporter’s Guide to Device and Personal Security in the Field&quot;">​</a></h2><p>Staying vigilant and using a combination of modern technology with traditional practices can significantly enhance personal and device security while reporting in high-risk areas. Always adapt to local conditions and remain aware of the evolving tactics used for tracking and surveillance.</p><p><strong>General Observations:</strong> 1. <strong>Underground Connectivity:</strong> - There is Wi-Fi signal in underground areas which can facilitate tracking even when not connected to Wi-Fi directly.</p><ul><li><p><strong>Extensive Tunnels:</strong></p></li><li><p>Extensive underground tunnels exist in Kyiv and Russia, historically used for disappearing.</p></li><li><p><strong>Tracking and Mapping:</strong></p></li><li><p>Personal tracking on apps like Strava can show location without interruptions even when underground.</p></li><li><p>Devices can be tracked through various networks, revealing movements and locations.</p></li><li><p><strong>Device Handling:</strong></p></li><li><p>Prefer physical SIM cards over eSIMs for ease of removal.</p></li><li><p>Use local SIM cards and avoid associating multiple devices to avoid pattern detection.</p></li><li><p>Devices should be kept isolated and never used near each other to prevent association.</p></li><li><p><strong>Faraday Bags:</strong></p></li><li><p>Effective for blocking signals. Multiple bags are needed for multiple devices.</p></li><li><p>Always test Faraday bags by attempting to send messages and checking for signal blockage.</p></li><li><p><strong>Device Security Practices:</strong></p></li><li><p>Changing personal phones frequently and upgrading regularly can help in avoiding tracking.</p></li><li><p>Monitor for odd behaviors around you, which could indicate tracking or targeting.</p></li><li><p><strong>Martial Law and Curfew:</strong></p></li><li><p>Breaking curfew can sometimes be a tactic to avoid being followed as fewer people are out at night.</p></li><li><p><strong>Interaction with Local Authorities:</strong></p></li><li><p>Awareness of local law enforcement and their methods can help in navigating safety.</p></li><li><p><strong>Travel Tips:</strong></p></li><li><p>When traveling to sensitive areas (e.g., Lebanon, Syria), maintain heightened security measures.</p></li><li><p>Be cautious with minders or followers, recognizing shifts and patterns.</p></li></ul><p><strong>Personal Security Tactics:</strong> 1. <strong>Behavioral Awareness:</strong> - Recognize and respond to unusual behavior from individuals around you. - Be mindful of cultural differences in expressions and behaviors.</p><ul><li><p><strong>Direct Confrontation:</strong></p></li><li><p>In certain situations, directly confronting a potential threat can be effective.</p></li><li><p><strong>Emergency Situations:</strong></p></li><li><p>Have tactics ready for dealing with potentially dangerous situations (e.g., engaging a suspicious cab driver).</p></li><li><p><strong>Tool Selection:</strong></p></li><li><p>Opt for non-lethal tools for self-defense, such as knives for practical purposes.</p></li><li><p>Carrying a gun might increase the risk of being targeted or mistaken for a spy.</p></li></ul><p><strong>Device and Contact Management:</strong> 1. <strong>Signal and Network Tracking:</strong> - Bluetooth and other signals can be used for tracking; avoid using Bluetooth devices like earpods. - Use secure messaging apps like Signal for contact management.</p><ul><li><p><strong>Organizational Practices:</strong></p></li><li><p>Keep contacts disorganized to make it harder for unauthorized access.</p></li><li><p>Prefer paper for sensitive information, avoiding digital storage.</p></li><li><p><strong>Password Management:</strong></p></li><li><p>Use password managers for securing information while maintaining ease of access.</p></li><li><p><strong>Memory and Local Knowledge:</strong></p></li><li><p>Develop a network with local reporters and rely on memory for critical contacts and information.</p></li></ul><p><strong>Media Training and Collaboration:</strong> 1. <strong>Lack of Device Security Training:</strong> - Recognize the gap in media training regarding device security. - Advocacy for collaboration between media organizations and national security agencies to enhance security measures.</p><ul><li><p><strong>Utilizing Old School Methods:</strong></p></li><li><p>Implement traditional methods like using rolodexes for contact management.</p></li><li><p>Build a personal memory system for critical information exchange.</p></li></ul>',11)])])}const f=i(r,[["render",o]]);export{u as __pageData,f as default};
